submissions.repair-original-inherit-report-subscript:
def solve(data):
    enabled = set(data['defaults'])
    for layer in data['layers']:
        if layer['state'] == 'active':
            enabled.update(layer['enable'])
            enabled.difference_update(layer['disable'])
    return sorted(enabled)

