                citations.append({
                    'id': citation['id'],
                    'start': offset + left - start,
                    'end': offset + right - start,
                })
        pieces.append(piece)
        offset += len(piece)
    return {'text': '\n'.join(pieces), 'citations': citations}

submissions.repair-original-normalize-rotated-tile-p:
def solve(data):
    w, h = data['width'], data['height']
    angle = data['rotation']
    dw, dh = (h, w) if angle in (90, 270) else (w, h)
    result = []
    for x, y in data['points']:
        if not (0 <= x < dw and 0 <= y < dh):
            result.append(None)
        elif angle == 90:
            result.append([y, h - 1 - x])
        elif angle == 180:
            result.append([w - 1 - x, h - 1 - y])
        elif angle == 270:
            result.append([w - 1 - y, x])
        else:
            result.append([x, y])
    return result
